-- What the person is asked to confirm. The command is asked, not copied: it
-- runs here and is always rolled back (the probe's own sqlstate leaves the
-- block), so what it refuses is refused before anyone is asked and nothing is
-- written. The confirmation maps only a few sqlstates to an answer; the
-- command's money-off (55000) and duplicate (23505) are put in those.
create or replace function public.mcp_target_create_membership_plan(p_workspace_id uuid, p_args jsonb)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_percent int;
  v_before jsonb;
begin
  perform public.mcp_setup_arguments(p_args, array['workspace_id', 'request_id', 'percent']);
  v_percent := (p_args->>'percent')::int;
  select subscription_levels into v_before from public.workspaces where id = p_workspace_id;
  begin
    perform public.create_subscription_level(p_workspace_id, v_percent);
    raise exception 'probe' using errcode = 'DKP01';
  exception
    when sqlstate 'DKP01' then null;
    when sqlstate '55000' then
      raise exception 'money is switched off in this space' using errcode = '42501';
    when sqlstate '23505' then
      raise exception 'this subscription level is already offered' using errcode = '22023';
  end;
  return jsonb_build_object('kind', 'membership_plan', 'percent', v_percent,
    'changes', jsonb_build_array(jsonb_build_object('field', 'subscription_level', 'from', null, 'to', v_percent)),
    'revision', md5(coalesce(v_before::text, '')));
end;
$fn$;
revoke execute on function public.mcp_target_create_membership_plan(uuid, jsonb) from public, anon, authenticated;

-- Runs only after the person confirmed the percentage. The command asks
-- manageBilling for the person again; this definer asks it first. The answer
-- says the plan was created and returns the plans now offered.
create or replace function public.mcp_op_create_membership_plan(c public.mcp_call_context, p_args jsonb)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_percent int;
  v_levels jsonb;
begin
  begin
    perform public.mcp_setup_arguments(p_args, array['workspace_id', 'request_id', 'percent']);
  exception when sqlstate 'DKS01' then
    return public.mcp_outcome('denied', null, 'secret_in_app_only');
  end;
  if not public.has_permission(c.workspace_id, 'manageBilling') then
    return public.mcp_outcome('denied', null, 'forbidden');
  end if;
  v_percent := (p_args->>'percent')::int;
  begin
    v_levels := public.create_subscription_level(c.workspace_id, v_percent);
  exception
    when insufficient_privilege then
      return public.mcp_outcome('denied', null, 'forbidden');
    when sqlstate '55000' then
      return public.mcp_outcome('denied', null, 'not_exposed');
  end;
  return public.mcp_outcome('completed', jsonb_build_object('created', true, 'percent', v_percent, 'levels', v_levels));
end;
$fn$;
revoke execute on function public.mcp_op_create_membership_plan(public.mcp_call_context, jsonb) from public, anon, authenticated;

